const LOOM_USER_PORTABLE_FORMAT='loom-user-portable/v1';

function loom_user_portability_set_add(array &$set,string $value): bool {
  $value=safe_token($value);if($value==='')return false;$new=!isset($set[$value]);$set[$value]=true;return $new;
}
function loom_user_portability_set(array $values): array { $s=[];foreach($values as $v)loom_user_portability_set_add($s,(string)$v);return $s; }
function loom_user_portability_ids(array $set): array { return array_keys($set); }
function loom_user_portability_has(array $set,?string $value): bool { $v=safe_token((string)$value);return $v!==''&&isset($set[$v]); }
function loom_user_portability_account_normalize(array $u): array {
  $uid=safe_token((string)($u['user_id']??$u['userId']??''));
  return [
    'userId'=>$uid,
    'username'=>(string)($u['username']??''),
    'usernameNorm'=>(string)($u['username_norm']??$u['usernameNorm']??loom_username_norm((string)($u['username']??''))),
    'email'=>(string)($u['email']??''),
    'emailNorm'=>(string)($u['email_norm']??$u['emailNorm']??loom_email_norm((string)($u['email']??''))),
    'passwordHash'=>(string)($u['password_hash']??$u['passwordHash']??''),
    'privilege'=>(string)($u['privilege']??'User'),
    'createdAt'=>(string)($u['created_at']??$u['createdAt']??server_timestamp()),
    'updatedAt'=>(string)($u['updated_at']??$u['updatedAt']??server_timestamp()),
  ];
}
function loom_user_portability_display_name(string $userId): string {
  $p=loom_global_profile_get('user',$userId);if(is_array($p)){$n=function_exists('loom_global_profile_display_name')?loom_global_profile_display_name($p):loom_clean_username((string)($p['displayName']??$p['username']??''));if($n!=='')return $n;}
  $u=loom_account_user_by_id($userId);$name=loom_clean_username((string)($u['username']??''));return $name!==''?$name:$userId;
