    $out[]=['userId'=>$uid,'displayName'=>loom_user_portability_display_name($uid),'email'=>$a['email'],'accountHandle'=>$a['username'],'privilege'=>$a['privilege'],'projectCount'=>count($projects),'isSystemOwner'=>$uid===loom_access_system_owner_user_id()];
