function loom_user_portability_db_values(string $sql,array $params=[]): array {
  if(!loom_db_ready())return [];try{$st=loom_db_pdo(true)->prepare($sql);$st->execute($params);return $st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){return [];}
