    foreach(loom_user_portability_db_values("SELECT client_id FROM loom_user_clients WHERE user_id=?",[$userId]) as $r)loom_user_portability_set_add($clients,(string)($r['client_id']??''));
    foreach(loom_user_portability_db_values("SELECT client_id FROM loom_clients WHERE user_id=?",[$userId]) as $r)loom_user_portability_set_add($clients,(string)($r['client_id']??''));
