  }
  $gs=loom_guest_store();
  // Expand client <-> Guest History ownership to a fixed point. Historical attachment rows count too.
  for($round=0;$round<4;$round++){$changed=false;foreach((array)($gs['guests']??[]) as $gid=>$g){$gid=safe_token((string)($g['guestId']??$gid));$hit=loom_user_portability_has($guests,$gid)||safe_token((string)($g['attachedUserId']??''))===$userId||loom_user_portability_has($clients,(string)($g['primaryClientId']??''));if(!$hit)foreach(array_keys((array)($g['clients']??[])) as $cid)if(loom_user_portability_has($clients,(string)$cid)){$hit=true;break;}if(!$hit)continue;if(loom_user_portability_set_add($guests,$gid))$changed=true;if(loom_user_portability_set_add($clients,(string)($g['primaryClientId']??'')))$changed=true;foreach(array_keys((array)($g['clients']??[])) as $cid)if(loom_user_portability_set_add($clients,(string)$cid))$changed=true;}
    if(loom_db_ready()&&$clients){$ids=array_keys($clients);$ph=implode(',',array_fill(0,count($ids),'?'));foreach(loom_user_portability_db_values("SELECT client_id,guest_id FROM loom_guest_clients WHERE client_id IN ($ph)",$ids) as $r){if(loom_user_portability_set_add($clients,(string)$r['client_id']))$changed=true;if(loom_user_portability_set_add($guests,(string)$r['guest_id']))$changed=true;}}
    if(loom_db_ready()&&$guests){$ids=array_keys($guests);$ph=implode(',',array_fill(0,count($ids),'?'));foreach(loom_user_portability_db_values("SELECT client_id,guest_id FROM loom_guest_clients WHERE guest_id IN ($ph)",$ids) as $r){if(loom_user_portability_set_add($clients,(string)$r['client_id']))$changed=true;if(loom_user_portability_set_add($guests,(string)$r['guest_id']))$changed=true;}}
    if(!$changed)break;
  }
  $gps=loom_guest_profiles_store();foreach((array)($gps['profiles']??[]) as $pid=>$p){$pid=safe_token((string)($p['guestProfileId']??$pid));$hit=safe_token((string)($p['lastClaimedUserId']??''))===$userId;foreach((array)($p['generations']??[]) as $g){if(safe_token((string)($g['userId']??''))===$userId||loom_user_portability_has($clients,(string)($g['clientId']??''))||loom_user_portability_has($guests,(string)($g['guestId']??''))){$hit=true;loom_user_portability_set_add($clients,(string)($g['clientId']??''));loom_user_portability_set_add($guests,(string)($g['guestId']??''));}}if($hit)loom_user_portability_set_add($profiles,$pid);}
  if(loom_db_ready()){
    foreach(loom_user_portability_db_values("SELECT DISTINCT guest_profile_id,client_id,guest_id FROM loom_guest_profile_generations WHERE user_id=?",[$userId]) as $r){loom_user_portability_set_add($profiles,(string)$r['guest_profile_id']);loom_user_portability_set_add($clients,(string)$r['client_id']);loom_user_portability_set_add($guests,(string)$r['guest_id']);}
    if($clients||$guests){$parts=[];$params=[];if($clients){$ids=array_keys($clients);$parts[]='client_id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$params=array_merge($params,$ids);}if($guests){$ids=array_keys($guests);$parts[]='guest_id IN ('.implode(',',array_fill(0,count($ids),'?')).')';$params=array_merge($params,$ids);}foreach(loom_user_portability_db_values("SELECT DISTINCT guest_profile_id,client_id,guest_id FROM loom_guest_profile_generations WHERE ".implode(' OR ',$parts),$params) as $r){loom_user_portability_set_add($profiles,(string)$r['guest_profile_id']);loom_user_portability_set_add($clients,(string)$r['client_id']);loom_user_portability_set_add($guests,(string)$r['guest_id']);}}
    foreach(loom_user_portability_db_values("SELECT guest_profile_id FROM loom_guest_profiles WHERE last_claimed_user_id=?",[$userId]) as $r)loom_user_portability_set_add($profiles,(string)$r['guest_profile_id']);
  }
