  return ['userIds'=>[$userId],'clientIds'=>array_keys($clients),'guestIds'=>array_keys($guests),'guestProfileIds'=>array_keys($profiles),'installationIds'=>array_keys($installs)];
}
function loom_user_portability_sets(array $graph): array { return [loom_user_portability_set($graph['userIds']??[]),loom_user_portability_set($graph['guestIds']??[]),loom_user_portability_set($graph['clientIds']??[]),loom_user_portability_set($graph['guestProfileIds']??[]),loom_user_portability_set($graph['installationIds']??[])]; }
function loom_user_portability_contains(mixed $v,array $sets): bool { return loom_cleanup_contains_ids($v,$sets); }
function loom_user_portability_recursive_remap(mixed $v,array $maps): mixed {
  if(is_array($v)){$out=[];foreach($v as $k=>$x){$nk=is_string($k)?loom_user_portability_remap_key($k,$maps):$k;$out[$nk]=loom_user_portability_recursive_remap($x,$maps);}return $out;}
  if(!is_string($v))return $v;foreach($maps as $map)if(isset($map[$v]))return $map[$v];return $v;
}
function loom_user_portability_remap_key(string $key,array $maps): string {
  if(str_contains($key,'|')){$parts=explode('|',$key);foreach($parts as &$p)foreach($maps as $m)if(isset($m[$p])){$p=$m[$p];break;}unset($p);return implode('|',$parts);}if(str_contains($key,':')){$parts=explode(':',$key);foreach($parts as &$p)foreach($maps as $m)if(isset($m[$p])){$p=$m[$p];break;}unset($p);return implode(':',$parts);}foreach($maps as $m)if(isset($m[$key]))return $m[$key];return $key;
}
function loom_user_portability_local_capture(array $graph): array {
