  $gp=[];foreach((loom_global_profile_store()['profiles']??[]) as $k=>$r){$t=(string)($r['ownerType']??$r['owner_type']??'');$id=safe_token((string)($r['ownerId']??$r['owner_id']??''));if(($t==='user'&&isset($users[$id]))||($t==='client'&&isset($clients[$id])))$gp[$k]=$r;}
  $pi=[];foreach((loom_project_identity_store()['identities']??[]) as $k=>$r){$t=(string)($r['ownerType']??$r['owner_type']??'');$id=safe_token((string)($r['ownerId']??$r['owner_id']??''));if(($t==='user'&&isset($users[$id]))||($t==='client'&&isset($clients[$id])))$pi[$k]=$r;}
  $state=[];foreach(glob(loom_project_state_dir().'/*.json')?:[] as $file){$project=basename($file,'.json');foreach((read_json_file($file)?:[]) as $k=>$r){foreach(array_keys($users) as $id)if(str_ends_with((string)$k,'|user|'.$id)){$state[$project][$k]=$r;continue 2;}foreach(array_keys($clients) as $id)if(str_ends_with((string)$k,'|client|'.$id)){$state[$project][$k]=$r;continue 2;}}}
  $gs=loom_guest_store();$guestSlice=['guests'=>[],'clientMap'=>[],'attachments'=>[],'conflicts'=>[]];foreach((array)($gs['guests']??[]) as $gid=>$r)if(isset($guests[safe_token((string)($r['guestId']??$gid))])){$copy=$r;$copy['recoveryHash']=null;$guestSlice['guests'][$gid]=$copy;}foreach((array)($gs['clientMap']??[]) as $cid=>$gid)if(isset($clients[safe_token((string)$cid)])||isset($guests[safe_token((string)$gid)]))$guestSlice['clientMap'][$cid]=$gid;foreach((array)($gs['attachments']??[]) as $k=>$r)if(loom_user_portability_contains($r,[$users,$guests,$clients,$profiles]))$guestSlice['attachments'][$k]=$r;foreach((array)($gs['conflicts']??[]) as $k=>$r)if(loom_user_portability_contains($r,[$users,$guests,$clients,$profiles]))$guestSlice['conflicts'][$k]=$r;
  $gps=loom_guest_profiles_store();$guestProfiles=['profiles'=>[],'installationMap'=>[],'clientProfileMap'=>[]];foreach((array)($gps['profiles']??[]) as $pid=>$r)if(isset($profiles[safe_token((string)($r['guestProfileId']??$pid))]))$guestProfiles['profiles'][$pid]=$r;foreach((array)($gps['installationMap']??[]) as $iid=>$pids)if(isset($installs[safe_token((string)$iid)]))$guestProfiles['installationMap'][$iid]=array_values(array_filter((array)$pids,fn($pid)=>isset($profiles[safe_token((string)$pid)])));foreach((array)($gps['clientProfileMap']??[]) as $cid=>$pid)if(isset($clients[safe_token((string)$cid)])||isset($profiles[safe_token((string)$pid)]))$guestProfiles['clientProfileMap'][$cid]=$pid;
  $moderation=loom_moderation_store();$mod=['identityStates'=>[],'projectStates'=>[],'audit'=>[]];foreach((array)($moderation['identityStates']??[]) as $k=>$r)if(loom_user_portability_contains($r,[$users,$guests,$clients,$profiles]))$mod['identityStates'][$k]=$r;foreach((array)($moderation['projectStates']??[]) as $project=>$rows)foreach((array)$rows as $k=>$r)if(loom_user_portability_contains([$k,$r],[$users,$guests,$clients,$profiles]))$mod['projectStates'][$project][$k]=$r;foreach((array)($moderation['audit']??[]) as $r)if(loom_user_portability_contains($r,[$users,$guests,$clients,$profiles]))$mod['audit'][]=$r;
