function loom_user_portability_db_table_rows(string $table,array $graph): array {
  if(!loom_db_ready())return [];[$users,$guests,$clients,$profiles,$installs]=loom_user_portability_sets($graph);$uid=(string)($graph['userIds'][0]??'');$pdo=loom_db_pdo(true);if(!$pdo)return [];
  $excluded=['loom_auth_sessions','loom_guest_recovery','loom_admin_state','loom_meta','loom_global_settings','loom_module_settings','loom_schema_migrations'];if(in_array($table,$excluded,true))return [];
  try{$cols=$pdo->query('SHOW COLUMNS FROM `'.str_replace('`','',$table).'`')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){return [];}$names=array_map(fn($c)=>(string)$c['Field'],$cols);$conds=[];$params=[];
  $addIn=function(string $col,array $set)use(&$conds,&$params,$names){if(!$set||!in_array($col,$names,true))return;$ids=array_keys($set);$conds[]='`'.$col.'` IN ('.implode(',',array_fill(0,count($ids),'?')).')';$params=array_merge($params,$ids);};
  foreach(['user_id','attached_user_id','last_claimed_user_id'] as $c)$addIn($c,$users);foreach(['client_id','source_client_id','primary_client_id'] as $c)$addIn($c,$clients);foreach(['guest_id','merged_into_guest_id'] as $c)$addIn($c,$guests);$addIn('guest_profile_id',$profiles);$addIn('installation_id',$installs);
  if(in_array('owner_type',$names,true)&&in_array('owner_id',$names,true)){if($users){$ids=array_keys($users);$conds[]="(`owner_type`='user' AND `owner_id` IN (".implode(',',array_fill(0,count($ids),'?')).'))';$params=array_merge($params,$ids);}if($clients){$ids=array_keys($clients);$conds[]="(`owner_type`='client' AND `owner_id` IN (".implode(',',array_fill(0,count($ids),'?')).'))';$params=array_merge($params,$ids);}}
  if(in_array('subject_type',$names,true)&&in_array('subject_id',$names,true)){if($users){$ids=array_keys($users);$conds[]="(`subject_type`='user' AND `subject_id` IN (".implode(',',array_fill(0,count($ids),'?')).'))';$params=array_merge($params,$ids);}foreach([$guests,$profiles] as $set)if($set){$ids=array_keys($set);$conds[]="(`subject_type`='guest' AND `subject_id` IN (".implode(',',array_fill(0,count($ids),'?')).'))';$params=array_merge($params,$ids);}}
  // Audit/history tables are allowed to include rows where this person was the actor/target.
  if(in_array($table,['loom_admin_audit','loom_audit_events'],true)){foreach(['admin_user_id','target_id'] as $c)$addIn($c,$users);$addIn('admin_client_id',$clients);}
  if($table==='loom_identity_audit'&&in_array('payload_json',$names,true)){foreach(array_merge(array_keys($users),array_keys($guests),array_keys($clients),array_keys($profiles)) as $id){$conds[]='`payload_json` LIKE ?';$params[]='%'.str_replace(['%','_'],['\\%','\\_'],$id).'%';}}
  if(!$conds)return [];try{$st=$pdo->prepare('SELECT * FROM `'.str_replace('`','',$table).'` WHERE '.implode(' OR ',$conds));$st->execute($params);return $st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){return [];}
}
function loom_user_portability_db_capture(array $graph): ?array {
  if(!loom_db_ready())return null;$pdo=loom_db_pdo(true);if(!$pdo)return null;$tables=[];foreach(loom_backup_db_tables($pdo) as $table){$rows=loom_user_portability_db_table_rows($table,$graph);if(!$rows)continue;$cols=[];try{foreach($pdo->query('SHOW COLUMNS FROM `'.str_replace('`','',$table).'`')->fetchAll() as $c)$cols[]=(string)$c['Field'];}catch(Throwable $e){}$tables[$table]=['columns'=>$cols,'rows'=>$rows,'rowCount'=>count($rows)];}
  return ['format'=>'loom-db-portable/v1','driver'=>'mysql','schemaVersion'=>loom_release_version(),'exportedAt'=>server_timestamp(),'excludedTables'=>['loom_auth_sessions','loom_guest_recovery','loom_admin_state'],'authenticationHashesIncluded'=>true,'tables'=>$tables];
}
function loom_user_portability_stream_capture(array $graph): array {
  $sets=loom_user_portability_sets($graph);$files=[];$roots=[loom_data_dir().'/logs'=> 'data/logs',loom_data_dir().'/replay'=>'data/replay',loom_audit_dir()=>'data/audit'];$identityAudit=function_exists('loom_identity_audit_file')?loom_identity_audit_file():'';if($identityAudit&&is_file($identityAudit))$roots[$identityAudit]='data/identity/audit.jsonl';
  foreach($roots as $root=>$label){$list=is_file($root)?[$root]:(is_dir($root)?(glob($root.'/*/*.jsonl')?:[]):[]);if(is_dir($root))$list=array_merge($list,glob($root.'/*.jsonl')?:[]);foreach(array_unique($list) as $file){if(!is_file($file))continue;$rows=[];foreach(@file($file,FILE_IGNORE_NEW_LINES)?:[] as $line){if(trim($line)==='')continue;$r=json_decode($line,true);if(is_array($r)&&loom_user_portability_contains($r,$sets))$rows[]=$r;}if(!$rows)continue;$rel=is_file($root)?$label:rtrim($label,'/').'/'.str_replace('\\','/',substr($file,strlen(rtrim($root,DIRECTORY_SEPARATOR))+1));$files[$rel]=$rows;}}
  return $files;
